export function formatDate(date, format = "M/d/y 'at' T") {
  if (!date) {
    return '';
  }
  return DateTime.fromMillis(date).toFormat(format);
}

/**
 * @param {number} unixTimestamp - timestamp as seconds since unix epoch
 * @returns {string} formatted date string e.g. "14 July 2034, 22:22"
 */
export const formatUTCDateFromUnixTimestamp = (unixTimestamp) => {
  if (!unixTimestamp) {
    return unixTimestamp;
  }

  return DateTime.fromSeconds(unixTimestamp)
    .toUTC()
    .toFormat('dd LLLL yyyy, HH:mm');
};

export function formatDateWithYearContext(
  date,
  formatThisYear = 'MMM d',
  fallback = 'MMM d, y',
) {
  if (!date) {
    return '';
  }
  const dateTime = DateTime.fromMillis(date);
  const now = DateTime.local();
  return dateTime.toFormat(
    now.year === dateTime.year ? formatThisYear : fallback,
  );
}

export function formatDateWithSuffix(timestamp) {
  const date = DateTime.fromMillis(timestamp * 1000); // Convert to milliseconds
  const { day } = date;
  const suffix = getOrdinalSuffix(day);

  return date.toFormat(`MMM d'${suffix}', yyyy`);
}

function getOrdinalSuffix(day) {
  if (day > 3 && day < 21) {
    return 'th';
  } // because 11th, 12th, 13th
  switch (day % 10) {
    case 1:
      return 'st';
    case 2:
      return 'nd';
    case 3:
      return 'rd';
    default:
      return 'th';
  }
}
export function valuesFor(obj) {
  if (!obj) {
    return [];
  }
  return Object.keys(obj).map(function (key) {
    return obj[key];
  });
}

export function isValidDomainName(address) {
  const match = punycode
    .toASCII(address)
    .toLowerCase()
    // Checks that the domain consists of at least one valid domain pieces separated by periods, followed by a tld
    // Each piece of domain name has only the characters a-z, 0-9, and a hyphen (but not at the start or end of chunk)
    // A chunk has minimum length of 1, but minimum tld is set to 2 for now (no 1-character tlds exist yet)
    .match(
      /^(?:[a-z0-9](?:[-a-z0-9]*[a-z0-9])?\.)+[a-z0-9][-a-z0-9]*[a-z0-9]$/u,
    );

  return match !== null;
}

/**
 * Checks if a name could potentially be resolved by name resolution services or Snaps.
 * This is more permissive than isValidDomainName to allow resolver Snaps to handle
 * various name formats like email-like names (yulia@beast), scheme-based names (ens:vitalik),
 * or other custom formats.
 *
 * @param {string} name - The name to check
 * @returns {boolean} True if the name could potentially be resolved
 */
export function isResolvableName(name) {
  // Must be a non-empty string
  if (!name || typeof name !== 'string') {
    return false;
  }

  const trimmed = name.trim();

  // Minimum length of 2 characters
  if (trimmed.length < 2) {
    return false;
  }

  // Reject if it looks like an Ethereum address (0x followed by 40 hex chars)
  if (/^0x[a-fA-F0-9]{40}$/u.test(trimmed)) {
    return false;
  }

  // Reject pure numbers
  if (/^\d+$/u.test(trimmed)) {
    return false;
  }

  // Reject URLs - check for common URL schemes early to avoid false positives
  const URL_SCHEMES = [
    'http',
    'https',
    'ftp',
    'ftps',
    'file',
    'mailto',
    'tel',
    'sms',
    'data',
    'blob',
    'javascript',
    'ws',
    'wss',
  ];
  if (trimmed.includes(':')) {
    const scheme = trimmed.split(':')[0].toLowerCase();
    if (URL_SCHEMES.includes(scheme)) {
      return false;
    }
  }

  // Accept if it matches traditional domain name format
  if (isValidDomainName(trimmed)) {
    return true;
  }

  // Accept email-like formats (contains @ with text on both sides)
  if (/^[^\s@]+@[^\s@]+$/u.test(trimmed)) {
    return true;
  }

  // Accept scheme-based formats (e.g., ens:vitalik, lens:username)
  if (/^[a-zA-Z][a-zA-Z0-9]*:[^\s]+$/u.test(trimmed)) {
    return true;
  }

  return false;
}

// Takes wei hex, returns wei bigint, even if input is null
export function numericBalance(balance) {
  if (!balance) {
    return 0n;
  }

  const stripped = stripHexPrefix(balance);
  if (!stripped) {
    return 0n;
  }

  return BigInt(`0x${stripped}`);
}

// Takes  hex, returns [beforeDecimal, afterDecimal]
export function parseBalance(balance) {
  let afterDecimal;
  const wei = numericBalance(balance);
  const weiString = wei.toString();
  const trailingZeros = /0+$/u;

  const beforeDecimal =
    weiString.length > 18 ? weiString.slice(0, weiString.length - 18) : '0';
  afterDecimal = `000000000000000000${wei}`
    .slice(-18)
    .replace(trailingZeros, '');
  if (afterDecimal === '') {
    afterDecimal = '0';
  }
  return [beforeDecimal, afterDecimal];
}

// Takes wei hex, returns an object with three properties.
// Its "formatted" property is what we generally use to render values.
export function formatBalance(
  balance,
  decimalsToKeep,
  needsParse = true,
  ticker = 'ETH',
) {
  const parsed = needsParse ? parseBalance(balance) : balance.split('.');
  const beforeDecimal = parsed[0];
  let afterDecimal = parsed[1];
  let formatted = 'None';
  if (decimalsToKeep === undefined) {
    if (beforeDecimal === '0') {
      if (afterDecimal !== '0') {
        const sigFigs = afterDecimal.match(/^0*(.{2})/u); // default: grabs 2 most significant digits
        if (sigFigs) {
          afterDecimal = sigFigs[0];
        }
        formatted = `0.${afterDecimal} ${ticker}`;
      }
    } else {
      formatted = `${beforeDecimal}.${afterDecimal.slice(0, 3)} ${ticker}`;
    }
  } else {
    afterDecimal += Array(decimalsToKeep).join('0');
    formatted = `${beforeDecimal}.${afterDecimal.slice(
      0,
      decimalsToKeep,
    )} ${ticker}`;
  }
  return formatted;
}

