/**
 * The type of installation of the extension.
 * - 'normal' means installed from official store (Chrome Web Store, Firefox Add-ons, etc.)
 * - 'development' means loaded unpacked in developer mode
 * - 'sideload' means installed by other software
 * - 'admin' means installed by admin policy (enterprise)
 * - 'other' means other installation type
 * - 'unknown' means the value hasn't been fetched yet or fetch failed
 */
export const INSTALL_TYPE = {
  ADMIN: 'admin',
  DEVELOPMENT: 'development',
  NORMAL: 'normal',
  SIDELOAD: 'sideload',
  OTHER: 'other',
  UNKNOWN: 'unknown',
} as const;

export type InstallType = (typeof INSTALL_TYPE)[keyof typeof INSTALL_TYPE];

/**
 * Device type for analytics: mobile or desktop.
 * - 'mobile' means the user-agent indicates a mobile device
 * - 'desktop' means the user-agent indicates a desktop device (default when UA is missing or inconclusive)
 */
export const DEVICE_TYPE = {
  DESKTOP: 'desktop',
  MOBILE: 'mobile',
} as const;

export type DeviceType = (typeof DEVICE_TYPE)[keyof typeof DEVICE_TYPE];

/**
 * Normalized operating system for analytics.
 */
export const OS = {
  ANDROID: 'Android',
  IOS: 'iOS',
  LINUX: 'Linux',
  MACOS: 'macOS',
  UNKNOWN: 'unknown',
  WINDOWS: 'Windows',
  /** Chrome OS, or other OS not in the main set */
  OTHER: 'Other',
} as const;

export type Os = (typeof OS)[keyof typeof OS];

